using Godot;
using System;
using System.Collections.Generic;
using System.Text.Json;
namespace MySim {
// Focused read-only follow-up to the broad audit. Symmetry/dimension matches remain hypotheses.
public static class ChironWingFocusedAttachmentAudit {
 sealed class Hypothesis {public string Label,Role;public Vector3 Point,Minimum,Maximum;public bool Closed;public int NormalSamples;public float MeanAbsNormalY;}
 static float[] A(Vector3 p)=>new[]{p.X,p.Y,p.Z};static Vector3 V(JsonElement p)=>new(p[0].GetSingle(),p[1].GetSingle(),p[2].GetSingle());
 static void Marker(Node3D car,Vector3 point,string label,Color colour){var node=new Node3D{Name="FocusedWing_"+label,Position=point};car.AddChild(node);node.AddChild(new MeshInstance3D{Mesh=new SphereMesh{Radius=.012f,Height=.024f,RadialSegments=12,Rings=6},MaterialOverride=new StandardMaterial3D{AlbedoColor=colour,ShadingMode=BaseMaterial3D.ShadingModeEnum.Unshaded}});node.AddChild(new Label3D{Text=label,Position=Vector3.Up*.035f,FontSize=28,PixelSize=.0014f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled,NoDepthTest=true,Modulate=colour});}
 public static void Write(Node3D car,int index,string path){
  ChironWingAttachmentAudit.Write(car,index,path,false);using var original=JsonDocument.Parse(System.IO.File.ReadAllText(path));var broad=original.RootElement.Clone();var inverse=car.GlobalTransform.AffineInverse();var bodyTriangles=new List<Vector3>();var strutPoints=new HashSet<Vector3>();
  foreach(var child in car.FindChildren("*","MeshInstance3D",true,false)){var mesh=(MeshInstance3D)child;if(!mesh.IsVisibleInTree()||mesh.Mesh==null)continue;string name=mesh.Name.ToString();bool strut=name.StartsWith("LOD_A_WING_STRUT_mm_",StringComparison.Ordinal),body=name.StartsWith("LOD_A_BODY_mm_",StringComparison.Ordinal);if(!strut&&!body)continue;var transform=inverse*mesh.GlobalTransform;foreach(var vertex in mesh.Mesh.GetFaces()){var point=transform*vertex;if(strut)strutPoints.Add(point);else bodyTriangles.Add(point);}}
  if(strutPoints.Count==0)throw new Exception("Focused wing audit has no intact main strut source");float lowest=float.PositiveInfinity,highest=float.NegativeInfinity;foreach(var p in strutPoints){lowest=Mathf.Min(lowest,p.Y);highest=Mathf.Max(highest,p.Y);}var endpoints=new List<object>();var bases=new Vector3[2];
  for(int side=0;side<2;side++)foreach(bool upper in new[]{false,true}){float edge=upper?highest:lowest;Vector3 centroid=Vector3.Zero;int count=0;var minimum=new Vector3(float.PositiveInfinity,float.PositiveInfinity,float.PositiveInfinity);var maximum=-minimum;foreach(var p in strutPoints)if((side==0?p.X<0:p.X>0)&&Mathf.Abs(p.Y-edge)<=.01f){centroid+=p;count++;minimum=minimum.Min(p);maximum=maximum.Max(p);}if(count==0)throw new Exception("Source strut extremity cannot be split into left/right clusters");centroid/=count;if(!upper)bases[side]=centroid;string label=(upper?"UT":"LB")+side;endpoints.Add(new{label,side,upper,samples=count,centroid=A(centroid),boundsMin=A(minimum),boundsMax=A(maximum),verifiedAttachment=false});Marker(car,centroid,label,new Color(1,.55f,.1f));}
  var hypotheses=new List<Hypothesis>();foreach(var item in broad.GetProperty("bodyBootBoundaryComponents").EnumerateArray()){
   var point=V(item.GetProperty("centroid"));if(point.Z> -1.7f||point.Y<.55f||Mathf.Abs(point.X)<.2f||Mathf.Abs(point.X)>.65f)continue;
   var h=new Hypothesis{Label=item.GetProperty("label").GetString(),Role=item.GetProperty("role").GetString(),Point=point,Minimum=V(item.GetProperty("boundsMin")),Maximum=V(item.GetProperty("boundsMax")),Closed=item.GetProperty("closedManifoldLoop").GetBoolean()};
   for(int i=0;i+2<bodyTriangles.Count;i+=3){var a=bodyTriangles[i];var b=bodyTriangles[i+1];var c=bodyTriangles[i+2];bool touches=false;foreach(var p in new[]{a,b,c})if(p.X>=h.Minimum.X-.001f&&p.X<=h.Maximum.X+.001f&&p.Y>=h.Minimum.Y-.001f&&p.Y<=h.Maximum.Y+.001f&&p.Z>=h.Minimum.Z-.001f&&p.Z<=h.Maximum.Z+.001f)touches=true;if(!touches)continue;var normal=(b-a).Cross(c-a);if(normal.LengthSquared()<1e-12f)continue;h.MeanAbsNormalY+=Mathf.Abs(normal.Normalized().Y);h.NormalSamples++;}if(h.NormalSamples>0)h.MeanAbsNormalY/=h.NormalSamples;hypotheses.Add(h);
  }
  var pairs=new List<(Hypothesis left,Hypothesis right,float symmetry,float spacingError,float rank)>();float sourceSpacing=bases[1].X-bases[0].X;
  foreach(var left in hypotheses)if(left.Point.X<0)foreach(var right in hypotheses)if(right.Point.X>0){var mirrored=new Vector3(-left.Point.X,left.Point.Y,left.Point.Z);float symmetry=mirrored.DistanceTo(right.Point);if(symmetry>.02f)continue;float spacingError=Mathf.Abs((right.Point.X-left.Point.X)-sourceSpacing);float rank=spacingError+symmetry+(left.Closed&&right.Closed?0:.025f);pairs.Add((left,right,symmetry,spacingError,rank));}pairs.Sort((a,b)=>a.rank.CompareTo(b.rank));
  var evidence=new List<object>();for(int i=0;i<pairs.Count;i++){var pair=pairs[i];bool shown=i<2;string leftLabel="P"+i+"L",rightLabel="P"+i+"R";evidence.Add(new{rank=i,leftSourceLabel=pair.left.Label,rightSourceLabel=pair.right.Label,left=A(pair.left.Point),right=A(pair.right.Point),symmetryError=pair.symmetry,sourceBaseSpacing=sourceSpacing,pairSpacing=pair.right.Point.X-pair.left.Point.X,spacingError=pair.spacingError,rankingScore=pair.rank,closedLoops=pair.left.Closed&&pair.right.Closed,leftNormalSamples=pair.left.NormalSamples,rightNormalSamples=pair.right.NormalSamples,leftMeanAbsNormalY=pair.left.MeanAbsNormalY,rightMeanAbsNormalY=pair.right.MeanAbsNormalY,shown,verifiedSockets=false});if(shown){Marker(car,pair.left.Point,leftLabel,new Color(.1f,1,.5f));Marker(car,pair.right.Point,rightLabel,new Color(.1f,1,.5f));}}
  System.IO.File.WriteAllText(path,JsonSerializer.Serialize(new{car=index,sourceAudit=broad,strutLeftRightExtremities=endpoints,rankedRearBodySymmetryPairs=evidence,maximumMarkers=8,scope="Read-only focused source-attachment hypotheses. Four orange labels measure split main-strut upper/lower tip bands; at most two green symmetric rear-body pairs ranked by measured strut-base spacing. No symmetry match, boundary seam, normal or ranking proves a mounting socket. No component moved; source transforms/UV/buffers/collision unchanged. Window/roof broad hypotheses excluded from display, not silently accepted."}));GD.Print("PASS focused Chiron rear attachment hypotheses; no sockets or reconstructed pose verified");
 }
}
}
